const cfg = $('Config — Łazikomat').first().json;
const now = new Date();
const toBool = (v) => ['true','1','yes','tak','active'].includes(String(v ?? '').trim().toLowerCase());
const candidates = items
  .map(i => i.json)
  .filter(r => toBool(r.Active))
  .filter(r => String(r.Platform || 'INSTAGRAM').toUpperCase() === 'INSTAGRAM')
  .filter(r => r.Username && !String(r.Username).includes('UZUPEŁNIJ'))
  .filter(r => {
    if (!r.Cooldown_Until) return true;
    const d = new Date(r.Cooldown_Until);
    return Number.isNaN(d.getTime()) || d <= now;
  })
  .sort((a,b) => {
    const pa = Number(a.Priority || 0);
    const pb = Number(b.Priority || 0);
    if (pb !== pa) return pb - pa;
    const la = a.Last_Selected_At ? new Date(a.Last_Selected_At).getTime() : 0;
    const lb = b.Last_Selected_At ? new Date(b.Last_Selected_At).getTime() : 0;
    return la - lb;
  })
  .slice(0, Number(cfg.dailyLimit || 30));

if (!candidates.length) {
  return [{json: {skip: true, reason: 'Brak profili poza cooldownem.'}}];
}

const fields = (username) =>
  `business_discovery.username(${username}){username,name,profile_picture_url,followers_count,media.limit(1){id,caption,permalink,timestamp,media_type}}`;

const batch = candidates.map(t => ({
  method: 'GET',
  relative_url: `${cfg.igUserId}?fields=${encodeURIComponent(fields(String(t.Username).replace(/^@/, '')))}`
}));

return [{
  json: {
    skip: false,
    selectedAt: now.toISOString(),
    candidates,
    batch
  }
}];

const selected = $('Select up to 30 + Build Meta Batch').first().json;
const raw = items[0]?.json;
const responses = Array.isArray(raw) ? raw : (Array.isArray(raw?.body) ? raw.body : raw);
if (!Array.isArray(responses)) {
  throw new Error(`Meta batch returned unexpected payload: ${JSON.stringify(raw).slice(0,800)}`);
}
const rows = selected.candidates.map((target, idx) => {
  const r = responses[idx] || {};
  let body = {};
  try { body = typeof r.body === 'string' ? JSON.parse(r.body) : (r.body || {}); } catch {}
  const bd = body.business_discovery || {};
  const media = bd.media?.data?.[0] || {};
  return {
    ...target,
    metaCode: r.code || 0,
    metaError: body.error?.message || '',
    Latest_Post_URL: media.permalink || target.Latest_Post_URL || '',
    Latest_Post_Caption: media.caption || '',
    Latest_Post_Timestamp: media.timestamp || '',
    Followers_Count: bd.followers_count || '',
    Profile_Name: bd.name || '',
  };
});
return [{json: {selectedAt: selected.selectedAt, rows}}];

const rows = $json.rows || [];
const payload = rows.map((r, i) => ({
  index: i,
  username: r.Username,
  category: r.Category || '',
  caption: String(r.Latest_Post_Caption || '').slice(0, 1200),
  url: r.Latest_Post_URL || '',
  error: r.metaError || ''
}));
const prompt = `You are the organic community assistant for VIRYA, a Polish modern/alternative metal band.
For each item, propose ONE brief, authentic comment that a real band member could leave manually.
Rules:
- use the language of the source caption when obvious; otherwise English;
- 4-18 words;
- reference a concrete detail from the caption;
- no generic "great post", no spam, no sales pitch, no asking for follows;
- no emojis unless the source tone clearly uses them;
- if the item has an error or no post URL, return an empty comment.
Return ONLY a valid JSON array of objects:
[{"index":0,"comment":"...","reason":"short internal reason"}]

INPUT:
${JSON.stringify(payload)}`;
return [{json: {...$json, geminiRequest: {
  contents: [{role: 'user', parts: [{text: prompt}]}],
  generationConfig: {
    temperature: 0.35,
    responseMimeType: 'application/json'
  }
}}}];

const cfg = $('Config — Łazikomat').first().json;
const source = $('Build Gemini Comment Prompt').first().json;
const resp = items[0]?.json || {};
const text = resp.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '[]';
let suggestions = [];
try {
  suggestions = JSON.parse(text.replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch {
  suggestions = [];
}
const byIndex = new Map((Array.isArray(suggestions) ? suggestions : []).map(x => [Number(x.index), x]));
const now = new Date(source.selectedAt || Date.now());
const review = new Date(now);
review.setDate(review.getDate() + Number(cfg.cooldownDays || 7));
const stamp = now.toISOString().replace(/[-:.TZ]/g,'').slice(0,14);

const logs = [];
const targets = [];
source.rows.forEach((r, i) => {
  const sug = byIndex.get(i) || {};
  const hasPost = Boolean(r.Latest_Post_URL);
  const status = r.metaError ? 'API_ERROR' : (hasPost ? 'QUEUED' : 'NEW');
  logs.push({
    Event_ID: `ENG-${stamp}-${String(i+1).padStart(2,'0')}`,
    Selected_At: now.toISOString(),
    Username: r.Username,
    Profile_URL: r.Profile_URL || `https://www.instagram.com/${String(r.Username).replace(/^@/,'')}/`,
    Platform: 'INSTAGRAM',
    Suggested_Action: hasPost ? 'MANUAL_LIKE_AND_COMMENT' : 'OPEN_PROFILE_MANUALLY',
    Latest_Post_URL: r.Latest_Post_URL || '',
    Suggested_Comment: hasPost ? String(sug.comment || '') : '',
    Completed_At: '',
    Review_After: review.toISOString(),
    Review_Status: 'PENDING',
    Outcome: '',
    Source: r.Source || 'ENGAGEMENT_TARGETS',
    Notes: r.metaError || String(sug.reason || '')
  });
  targets.push({
    Active: r.Active,
    Username: r.Username,
    Profile_URL: r.Profile_URL || `https://www.instagram.com/${String(r.Username).replace(/^@/,'')}/`,
    Platform: 'INSTAGRAM',
    Category: r.Category || '',
    Priority: r.Priority || '',
    Source: r.Source || '',
    Last_Selected_At: now.toISOString(),
    Cooldown_Until: review.toISOString(),
    Interaction_Status: status,
    Latest_Post_URL: r.Latest_Post_URL || '',
    Latest_Post_Caption: r.Latest_Post_Caption || '',
    Suggested_Comment: hasPost ? String(sug.comment || '') : '',
    Notes: r.metaError || r.Notes || ''
  });
});
return [{json:{logs, targets}}];

const logs = $('Prepare Sheet Rows').first().json.logs || [];
const usable = logs.filter(x => x.Profile_URL);
const chunks = [];
for (let i=0; i<usable.length; i+=10) {
  const block = usable.slice(i,i+10).map((x, j) => {
    const n = i+j+1;
    const action = x.Latest_Post_URL || x.Profile_URL;
    const comment = x.Suggested_Comment ? `\n💬 ${x.Suggested_Comment}` : '';
    return `**${n}. @${String(x.Username).replace(/^@/,'')}**\n🔗 ${action}${comment}`;
  }).join('\n\n');
  chunks.push({
    message: `## VIRYA — organic engagement ${i+1}-${Math.min(i+10, usable.length)}/${usable.length}\nKliknij ręcznie, przeczytaj post i reaguj tylko wtedy, gdy komentarz naprawdę pasuje.\n\n${block}`
  });
}
return chunks.map(x => ({json:x}));

const now = new Date();
const due = items.map(i=>i.json).filter(r => {
  if (String(r.Review_Status || '').toUpperCase() !== 'PENDING') return false;
  if (!r.Review_After) return false;
  const d = new Date(r.Review_After);
  return !Number.isNaN(d.getTime()) && d <= now;
});
if (!due.length) return [];
const chunks = [];
for (let i=0; i<due.length; i+=15) {
  const text = due.slice(i,i+15).map((r,j) =>
    `**${i+j+1}. @${String(r.Username||'').replace(/^@/,'')}** — ${r.Profile_URL || ''}\n` +
    `Zmień w ENGAGEMENT_LOG: Review_Status → KEEP / ARCHIVE / SKIP.`
  ).join('\n\n');
  chunks.push({message:`## VIRYA — 7-dniowy przegląd relacji\nTo nie jest automatyczne odlajkowanie. Sprawdź, czy profil jest wartościowy i zdecyduj ręcznie.\n\n${text}`});
}
return chunks.map(x=>({json:x}));
